argv:
$ErrorActionPreference='Continue'
$o=[ordered]@{at=(Get-Date).ToUniversalTime().ToString('o')}
try {$s=Invoke-RestMethod 'http://127.0.0.1:8080/api/status' -TimeoutSec 5;$e=[string]$s.tunnel_metadata_error;$o.metadataErrorPresent=($e.Length -gt 0);$o.regionBlocked=($e -match 'unsupported_country_region_territory|country, region, or territory not supported');$o.httpStatus=if($e -match '(?<!\d)(400|401|403|404|409|424|429|500|502|503)(?!\d)'){$Matches[1]}else{'none'};$o.uptimeSeconds=$s.uptime_seconds;$o.routeCount=@($s.mcp_routes).Count} catch {$o.operatorError='unavailable'}
try {$m=(Invoke-WebRequest 'http://127.0.0.1:8080/metrics' -UseBasicParsing -TimeoutSec 4).Content;$o.poll=@($m -split [char]10 | Where-Object {$_ -match '^(commands_poll_(cycles_total|errors_total|last_successful_timestamp_seconds))(\{[^}]*\})?\s+[-+0-9.eE]+'} | Select-Object -First 20 | ForEach-Object {[regex]::Replace($_,'\{[^}]*\}','{LABELS_REDACTED}')})} catch {$o.metricsError='unavailable'}
$o|ConvertTo-Json -Compress -Depth 4
